-- Q1 [Mendelian Foundations] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mendelian Foundations', 'A geneticist examines a pair of homologous chromosomes in a diploid cell and notes that the gene for seed color sits at the identical band on both members of the pair. The fixed chromosomal address occupied by that gene is most accurately termed its', '[{"label": "A", "text": "locus"}, {"label": "B", "text": "allele"}, {"label": "C", "text": "genotype"}, {"label": "D", "text": "chromatid"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is A because the locus is the fixed physical position that a gene occupies on a chromosome. The OpenStax glossary defines locus as the "position of a gene on a chromosome," and the text states that homologous chromosomes "have specific nucleotide segments called genes in exactly the same location, or locus." Because homologous chromosomes are matched pairs that carry the same genes in the same order, the seed-color gene maps to the same locus on each homolog, even though the two copies may carry different alleles. (Choice A) is correct: the locus is the chromosomal address of the gene, and corresponding genes line up at identical loci on the two homologs. (Choice B) names an allele, which is one alternative version of the gene that resides at the locus, not the position itself; the text notes that the genes at matching loci on the two homologs "are not identical" because they may be different alleles, so an allele is the variant occupying the site rather than the site. (Choice C) names a genotype, which is the combination of alleles an organism carries for a gene, again describing the genetic content rather than the physical position on the chromosome. (Choice D) names a chromatid, which is one of the two duplicated DNA strands of a single chromosome held together at the centromere, an entire structural copy of the chromosome rather than the specific spot where one gene sits. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition of a locus and how genes are positioned on homologous chromosomes.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 70)
  RETURNING id
)
