-- Q2 [Mendelian Foundations] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mendelian Foundations', 'In a pea population where the allele for violet flowers (\(A\)) is completely dominant over the allele for white flowers (\(a\)), a researcher grows two violet-flowered plants that appear identical. Which finding is most consistent with Mendelian inheritance in this dominant–recessive system?', '[{"label": "A", "text": "Both plants must carry the genotype \\(aa\\)"}, {"label": "B", "text": "Both plants must carry the genotype \\(Aa\\)"}, {"label": "C", "text": "The plants must share an identical genotype"}, {"label": "D", "text": "One plant may be \\(AA\\) while the other is \\(Aa\\)"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because in a dominant–recessive system the violet phenotype is produced by both the homozygous dominant and the heterozygous genotype, so two violet plants can carry different genotypes. The phenotype is the observable trait, whereas the genotype is the organism''s underlying allele combination, and OpenStax states that for a gene expressed in a dominant and recessive pattern, "homozygous dominant and heterozygous organisms will look identical (that is, they will have different genotypes but the same phenotype)." Because a single dominant \(A\) allele is sufficient to mask the recessive \(a\) allele, both \(AA\) and \(Aa\) plants display violet flowers, and only the homozygous recessive \(aa\) genotype yields the white phenotype. Identical appearance therefore does not require identical genotype. (Choice A) is incorrect because \(aa\) is the homozygous recessive genotype, which would produce white flowers, not the observed violet phenotype. (Choice B) is incorrect because, although \(Aa\) does give violet flowers, it is not the only genotype that does so; a violet plant could equally be \(AA\), so neither plant is required to be heterozygous. (Choice C) is incorrect because it reverses the genotype–phenotype relationship by assuming matching phenotypes guarantee matching genotypes, whereas different genotypes (\(AA\) and \(Aa\)) can yield the same phenotype. (Choice D) is correct: a dominant allele needs only one copy to be expressed, so the two phenotypically identical violet plants may legitimately differ, with one homozygous dominant (\(AA\)) and the other heterozygous (\(Aa\)). This is a Knowledge of Scientific Concepts and Principles question because you must recall the distinction between genotype and phenotype and that a dominant trait arises from more than one genotype.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 75)
  RETURNING id
)
