-- Q3 [Mendelian Foundations] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mendelian Foundations', 'A pea plant inherits one allele for violet flowers (\(V\)) and one allele for white flowers (\(v\)), where violet is fully dominant. The plant produces violet flowers. Regarding the white-flower allele in this heterozygous plant, which outcome is most consistent with Mendel''s law of dominance?', '[{"label": "A", "text": "It produces flowers of an intermediate, pale-violet color"}, {"label": "B", "text": "It remains latent and is not expressed in the phenotype"}, {"label": "C", "text": "It is expressed simultaneously alongside the violet allele"}, {"label": "D", "text": "It is the only allele transmitted to the gametes"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is B because under Mendel''s law of dominance the dominant allele is expressed exclusively in a heterozygote, so the recessive white-flower allele stays latent and makes no contribution to the phenotype. Mendel''s law of dominance states that in a heterozygote, one trait will conceal the presence of another trait for the same characteristic, with the dominant allele expressed exclusively while the recessive allele remains \"latent\" but is still transmitted to offspring. Because of this, a homozygous dominant (\(VV\)) plant and a heterozygous (\(Vv\)) plant look identical, and the recessive trait is observed only in homozygous recessive (\(vv\)) individuals. (Choice A) The intermediate, blended phenotype describes incomplete dominance, in which the heterozygote displays a phenotype between the two parents (as in a pink \(C^R C^W\) snapdragon); this is an exception to simple dominance, not what occurs when violet is fully dominant. (Choice B) is correct: under full dominance the recessive allele is masked and contributes nothing to the phenotype, though it is still passed on intact to the next generation. (Choice C) Simultaneous expression of both alleles in the heterozygote defines codominance (as in the MN blood groups), not the simple dominant/recessive pattern described here. (Choice D) The recessive allele is transmitted to gametes by the same manner as the dominant allele, so the dominant allele is not the only one passed on; this reverses the fact that segregation gives each gamete one allele of the pair. This is a Knowledge of Scientific Concepts and Principles question because you must recall that, in a heterozygote, a fully dominant allele is expressed exclusively while the recessive allele remains latent.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 70)
  RETURNING id
)
