-- Q4 [Mendelian Foundations] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mendelian Foundations', 'A couple in which neither parent shows cystic fibrosis, a recessive disorder, has a child who expresses the disease. The child most likely exhibits the recessive phenotype while the parents do not because the child is the only one of the three who:', '[{"label": "A", "text": "carries a single copy of the recessive allele"}, {"label": "B", "text": "inherited the recessive allele only from the mother"}, {"label": "C", "text": "carries two copies of the recessive allele"}, {"label": "D", "text": "expresses the dominant allele exclusively"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is C because the recessive cystic fibrosis phenotype appears only when an individual is homozygous recessive, carrying two copies of the recessive allele. The textbook states that for a gene expressed in a dominant and recessive pattern, "The traits of the recessive allele will only be observed in homozygous recessive individuals," and that "The recessive trait will only be expressed by offspring that have two copies of this allele." Both unaffected parents are heterozygous carriers, each holding one recessive allele that remains "latent" and makes no contribution to the phenotype because the dominant allele is expressed exclusively; only their child, who received a recessive allele from each parent, is homozygous recessive \(aa\) and therefore expresses the disease. (Choice A) is incorrect: a single copy of the recessive allele describes the heterozygous carrier state of each parent, in which the recessive allele is hidden and not expressed, so it cannot explain why the child is affected. (Choice B) is incorrect: a recessive phenotype requires a recessive allele from BOTH parents, not just the mother; cystic fibrosis is autosomal, so inheriting the allele from only one parent would leave the child as a heterozygous carrier rather than affected. (Choice C) is correct: only the child is homozygous recessive, having inherited one recessive allele from each carrier parent, which is the two-copy requirement for expressing a recessive trait; the parents each carry only one copy and so remain unaffected. (Choice D) is incorrect: exclusive expression of the dominant allele describes the unaffected parents (and any unaffected child), in whom the dominant allele masks the recessive one, which is the opposite of the affected child''s situation. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that a recessive phenotype requires two copies of the recessive allele to a specific pedigree situation and identify the child''s unique homozygous recessive genotype.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 105)
  RETURNING id
)
