-- Q5 [Mendelian Foundations] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mendelian Foundations', 'A geneticist records the single-locus genotypes of four diploid individuals as \(VV\), \(vv\), \(L^M L^M\), and \(I^A I^B\). Which individual is heterozygous at that locus?', '[{"label": "A", "text": "The \\(VV\\) individual"}, {"label": "B", "text": "The \\(vv\\) individual"}, {"label": "C", "text": "The \\(L^M L^M\\) individual"}, {"label": "D", "text": "The \\(I^A I^B\\) individual"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because the \(I^A I^B\) individual carries two different alleles at the locus, which is the definition of heterozygous. A diploid organism is heterozygous when its two alleles for a gene differ from each other; the textbook states that when parents with contrasting traits were crossed, the offspring were ''heterozygous for the contrasting trait, meaning that their genotype reflected that they had different alleles for the gene being examined.'' By contrast, an organism is homozygous when it has ''two identical alleles for that gene on their homologous chromosomes.'' Classification depends only on whether the two alleles are identical or different, not on whether the letters are uppercase, lowercase, or carry superscripts. (Choice A) is incorrect because \(VV\) consists of two identical dominant alleles, making it homozygous dominant; the textbook designates \(VV\) as the genotype of ''a homozygous dominant pea plant.'' (Choice B) is incorrect because \(vv\) consists of two identical recessive alleles and is therefore homozygous recessive, designated for ''a homozygous recessive pea plant.'' (Choice C) is incorrect because \(L^M L^M\) carries two copies of the same \(L^M\) allele; the textbook lists genotypes such as \(L^M L^M\) among ''Homozygotes,'' so two matching superscripted alleles are still homozygous. (Choice D) is correct: \(I^A I^B\) pairs two distinct alleles (\(I^A\) and \(I^B\)) at one locus, satisfying the definition of having ''different alleles for the gene being examined''; both alleles happening to be dominant or codominant does not change the fact that the two alleles are non-identical, so the individual is heterozygous. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of homozygous and heterozygous to classify specific genotype strings rather than simply restate the definitions.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 100)
  RETURNING id
)
