-- Q6 [Mendelian Foundations] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mendelian Foundations', 'A woman who is an unaffected carrier of an X-linked recessive hemophilia allele has a son who inherits that single recessive allele on his X chromosome and expresses hemophilia. The expression of the trait in this hemizygous son is most directly explained by which feature of his genotype?', '[{"label": "A", "text": "He carries only one allele for the gene, with none to mask it"}, {"label": "B", "text": "The recessive allele behaves dominantly in male offspring"}, {"label": "C", "text": "He inherited two copies of the recessive allele"}, {"label": "D", "text": "X inactivation silenced his wild-type allele"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is A because an XY male is hemizygous and carries only a single allele for any X-linked gene, so there is no second allele that could mask the recessive one. Because the gene is present on the X chromosome but not on the Y, the son''s genotype is \(X^h Y\) and he receives exactly one copy of the X-linked locus; the textbook states that "Males are said to be hemizygous, because they have only one allele for any X-linked characteristic" and that "Hemizygosity makes the descriptions of dominance and recessiveness irrelevant for XY males." Whatever single allele he inherits is therefore expressed directly, which is why "human males need to inherit only one recessive mutant X allele to be affected." (Choice A) is correct: with a single X-linked allele and no homologous partner on the Y, the recessive allele is the only one present and is expressed regardless of its dominance classification. (Choice B) misstates the mechanism as a reversed relationship: the recessive allele does not become dominant in males; rather, dominance and recessiveness are simply irrelevant because there is no second allele for it to act against. (Choice C) confuses the male situation with the female one: the textbook notes that "Females must inherit recessive X-linked alleles from both of their parents in order to express the trait" (an \(X^h X^h\) genotype), but a hemizygous \(X^h Y\) son has only one X and therefore only one copy of the allele, not two. (Choice D) names a real but misapplied process: X inactivation can cause carrier females (genotype \(X^H X^h\)) to manifest mild forms of a trait by silencing the dominant wild-type allele on one X, but a hemizygous male has no second X to inactivate and no wild-type allele to silence. This is a Scientific Reasoning and Problem Solving question because you must apply the principle of hemizygosity to a specific inheritance scenario to identify why a single recessive X-linked allele is expressed.', 'medium', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 105)
  RETURNING id
)
