-- Q9 [Mendelian Foundations] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Mendelian Foundations', 'In a family, a particular trait is absent in both parents but appears in one of their children, and the trait is known to follow a simple recessive inheritance pattern. Which combination of genotypes most likely accounts for these observations?', '[{"label": "A", "text": "Both parents are \\(AA\\); the affected child is \\(Aa\\)"}, {"label": "B", "text": "One parent is \\(aa\\); the affected child is \\(Aa\\)"}, {"label": "C", "text": "Both parents are \\(Aa\\); the affected child is \\(Aa\\)"}, {"label": "D", "text": "Both parents are \\(Aa\\); the affected child is \\(aa\\)"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because a recessive trait can appear in a child of two unaffected parents only if both parents are heterozygous carriers (\(Aa\)) who each pass the recessive allele, producing a homozygous recessive (\(aa\)) affected child. By the law of dominance, a recessive trait is expressed only by offspring carrying two copies of the recessive allele, so the affected child must be \(aa\); because neither parent expresses the trait, each parent must carry one masked recessive allele alongside a dominant allele, making both \(Aa\). OpenStax states directly that in such a pedigree "if neither parent has the disorder but their child does, they must be heterozygous," and that affected individuals "have the genotype aa" while unaffected individuals have genotype \(AA\) or \(Aa\). The two heterozygous parents segregate their alleles equally into gametes, giving each child a \(1/4\) chance of inheriting two recessive alleles. (Choice A) is wrong because two \(AA\) parents carry no recessive allele to transmit, so no child could be affected; furthermore an \(Aa\) child would itself be an unaffected carrier, not affected. (Choice B) reverses the situation: an \(aa\) parent would visibly express the recessive trait, contradicting the premise that both parents are unaffected, and an \(Aa\) child would again be an unaffected carrier rather than showing the trait. (Choice C) is a partial truth that correctly identifies both parents as heterozygous but errs on the child, because a heterozygous \(Aa\) child has a dominant allele that masks the recessive trait and would therefore be unaffected; only a homozygous recessive child expresses the trait. (Choice D) is correct: two carrier parents (\(Aa \times Aa\)) can produce an \(aa\) child who inherits one recessive allele from each parent and thus expresses the recessive trait. This is a Scientific Reasoning and Problem Solving question because you must apply the law of dominance and equal segregation to infer unobserved genotypes from a pattern of phenotypes across two generations.', 'hard', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 150)
  RETURNING id
)
