-- Q10 [Dominance Patterns] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Dominance Patterns', 'In garden peas, flower color follows a complete-dominance pattern in which the violet allele is dominant to the white allele. A breeder crosses a true-breeding violet plant \(VV\) with a true-breeding white plant \(vv\) and examines the heterozygous \(Vv\) offspring. Which flower phenotype do these offspring most likely display?', '[{"label": "A", "text": "Violet, identical to the homozygous-dominant parent"}, {"label": "B", "text": "Pale lavender, intermediate between violet and white"}, {"label": "C", "text": "Violet and white patches expressed together"}, {"label": "D", "text": "White, identical to the homozygous-recessive parent"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is A because under complete dominance the heterozygote and the homozygous-dominant individual share the same phenotype while the recessive allele is fully masked. In a gene expressed in a dominant and recessive pattern, homozygous dominant and heterozygous organisms look identical, having different genotypes but the same phenotype, and the recessive trait appears only in homozygous recessive individuals (OpenStax Biology 2e, lines 14739-14742). Because the violet allele is completely dominant, the \(Vv\) heterozygote expresses the full violet phenotype of the \(VV\) parent; in the presence of the dominant allele, the recessive allele is hidden and makes no contribution to the phenotype (lines 14892-14893). (Choice A) is correct: the heterozygote matches the homozygous-dominant violet plant, which is the defining feature of complete dominance and the reason the white allele can be silently carried by violet-flowered carriers. (Choice B) describes incomplete dominance, in which two contrasting alleles produce an intermediate phenotype such as the pink snapdragon heterozygote (lines 14906-14908); complete dominance produces no blended intermediate. (Choice C) describes codominance, in which both alleles are simultaneously expressed in the heterozygote, as with the M and N blood-group antigens (lines 14925-14929); under complete dominance only the dominant allele''s phenotype appears. (Choice D) reverses the dominance relationship, since the recessive white trait is observed only in homozygous recessive \(vv\) individuals, not in heterozygotes (lines 14741-14742). This is a Knowledge of Scientific Concepts and Principles question because you must recall that in complete dominance the heterozygote phenotype is identical to the homozygous-dominant phenotype.', 'easy', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 1, 75)
  RETURNING id
)
