-- Q24 [Dominance Patterns] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Dominance Patterns', 'A geneticist crosses a true-breeding red-flowered plant with a true-breeding white-flowered plant. Every \(F_1\) heterozygote bears blossoms with distinct red and white patches, with both colors fully and separately visible on a single flower. The inheritance pattern most consistent with this observation is:', '[{"label": "A", "text": "incomplete dominance"}, {"label": "B", "text": "complete dominance"}, {"label": "C", "text": "codominance"}, {"label": "D", "text": "multiple alleles"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is C because the heterozygote expresses both parental alleles fully and simultaneously, which is the defining outcome of codominance. OpenStax states that in codominance ''both alleles for the same characteristic are simultaneously expressed in the heterozygote,'' using the MN blood groups as an example where heterozygotes ''(LMLN) express both alleles equally.'' The key data here is that the red and white phenotypes appear distinct and fully visible on the same flower rather than blending, which rules out an intermediate phenotype. (Choice A) is incorrect because incomplete dominance produces a heterozygote that ''displays an intermediate phenotype'' — the textbook''s snapdragon cross of red (CRCR) and white (CWCW) yields blended pink (CRCW), not separate red and white patches. (Choice B) is incorrect because under complete dominance the heterozygote resembles only one parent, expressing the dominant trait while the recessive trait is ''non-expressed,'' so a single parental color (not both) would appear. (Choice C) is correct: codominance is the simultaneous, full expression of both alleles in the heterozygote, exactly matching blossoms that show both red and white distinctly. (Choice D) is incorrect because multiple alleles refers to a gene for which ''more than two alleles of a gene'' exist in a population; this cross involves two alleles and describes how they are expressed in the heterozygote, not how many alleles exist. This is a Scientific Reasoning and Problem Solving question because you must apply the definitions of non-Mendelian dominance patterns to the phenotypic data to infer the underlying mechanism.', 'hard', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 150)
  RETURNING id
)
