-- Q25 [Dominance Patterns] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Genetics and Evolution', 'Dominance Patterns', 'In rabbits, coat color is governed by a single gene with four alleles arranged in a dominance hierarchy: wild-type \(C^+\) (brown), chinchilla \(c^{ch}\) (black-tipped white), Himalayan \(c^h\) (black extremities, white elsewhere), and albino \(c\) (white). A breeder crosses two rabbits and recovers a kit with the genotype \(c^h c\). Based on the allelic series, the kit''s coat most likely appears as which phenotype?', '[{"label": "A", "text": "Uniformly brown fur"}, {"label": "B", "text": "Entirely white fur"}, {"label": "C", "text": "Black-tipped white fur"}, {"label": "D", "text": "Black extremities, white elsewhere"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Transmission of Heritable Information from Generation to Generation.'' The answer is D because in the rabbit coat-color allelic series the textbook states that "Himalayan is dominant over albino," so a \(c^h c\) heterozygote expresses the phenotype dictated by the higher-ranked Himalayan allele rather than the recessive albino allele. OpenStax describes the Himalayan phenotype, \(c^h c^h\), as having "black fur on the extremities and white fur elsewhere," and because \(c^h\) is fully dominant to \(c\), the \(c^h c\) kit shows that same Himalayan coat (lines 14942-14948). The albino allele is the most recessive member of the series, so its phenotype is masked whenever any higher-ranked allele is present. (Choice A) is incorrect because uniformly brown fur is the wild-type \(C^+\) phenotype, and the kit carries no wild-type allele; brown requires at least one \(C^+\), which is "dominant over all the others" (lines 14942-14946). (Choice B) is incorrect because entirely white fur is the albino \(c c\) phenotype, which appears only when the recessive \(c\) is homozygous; here \(c^h\) outranks \(c\), so the albino phenotype is masked (lines 14944-14947). (Choice C) is incorrect because black-tipped white fur is the chinchilla \(c^{ch}\) phenotype, and the kit carries no chinchilla allele, so that coat cannot appear (line 14943). (Choice D) is correct: because Himalayan is dominant over albino, the \(c^h c\) genotype yields the Himalayan coat of black extremities with white fur elsewhere (lines 14944-14947). This is a Scientific Reasoning and Problem Solving question because you must apply the stated dominance ranking to a heterozygous genotype to predict which allele''s phenotype is expressed.', 'hard', '1C', 'Transmission of Heritable Information from Generation to Generation', 'biology', 2, 150)
  RETURNING id
)
